-- 📚 꼭집 주거 사전 — LH 공고 페이지 접수기간 ↔ 카드(공고문) 갈림
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: source_page_checks 원문 키마다 마지막 오류 없는 대조 한 건(열린 카드만 대조됨).
-- 확인 2026-10-14 · 결과 요지: LH keys 74 · end_diff 3(…20730 · …20825 · …20898) · start_diff 0 · closed_mismatch 0 / SH keys 6 · 다름 0 · 기간 2026-10-08~10-13
with last as(select distinct on(source,source_key)* from source_page_checks where error is null order by source,source_key,checked_at desc)select json_agg(json_build_object('source',source,'keys',keys,'end_diff',ed,'start_diff',sd,'closed_mismatch',cm,'first',f,'last',l,'ex',ex)) j from(select source,count(*)keys,count(*) filter(where end_diff)ed,count(*) filter(where start_diff)sd,count(*) filter(where closed_mismatch)cm,min(checked_at)::date f,max(checked_at)::date l,(select json_agg(json_build_object('card',l2.card_id,'page_end',l2.page_apply_end,'card_end',l2.card_apply_end)) from last l2 where l2.source=last.source and(l2.end_diff or l2.start_diff))ex from last group by source)q;
